//! Acceptance test: the shared test vectors of the spec baseline
//! (`oec/spec/export/`, generated by `spectool render`, ADR-0026).

use std::path::PathBuf;

use oec_core::il::{IdentificationLink, Oi4Identifier, Violation, dnp_encode};
use oec_core::topic::{FilterKind, Form, Method, Resource, Service, Subject, Topic};
use serde_json::Value;

fn load(rel: &str) -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../../spec/export")
        .join(rel);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn vectors(rel: &str) -> Vec<Value> {
    let v = load(rel)["vectors"].as_array().cloned().unwrap_or_default();
    assert!(!v.is_empty(), "{rel}: no vectors");
    v
}

fn str_field<'a>(v: &'a Value, key: &str) -> Option<&'a str> {
    v.get(key).and_then(Value::as_str)
}

fn strings(v: &Value, key: &str) -> Vec<String> {
    v.get(key)
        .and_then(Value::as_array)
        .map(|a| a.iter().map(|s| s.as_str().unwrap().to_owned()).collect())
        .unwrap_or_default()
}

fn valid(v: &Value) -> bool {
    match str_field(v, "expected") {
        Some("valid") => true,
        Some("invalid") => false,
        other => panic!("{}: expected = {other:?}", v["id"]),
    }
}

fn codes(violations: &[Violation]) -> Vec<String> {
    violations.iter().map(|x| x.code().to_owned()).collect()
}

#[test]
fn identification_link() {
    for v in vectors("vectors/il-identification-link.json") {
        let id = &v["id"];
        let il = str_field(&v, "il");
        let encoded = str_field(&v, "encoded");
        if valid(&v) {
            let link =
                IdentificationLink::parse(il.unwrap()).unwrap_or_else(|e| panic!("{id}: {e}"));
            assert_eq!(link.as_str(), il.unwrap(), "{id}");
            if let Some(enc) = encoded {
                assert_eq!(link.encode(), enc, "{id}");
                assert_eq!(IdentificationLink::decode(enc).as_ref(), Ok(&link), "{id}");
            }
        } else {
            let want = strings(&v, "violations");
            // Without "il" the vector is a topic element; an omitted
            // "encoded" is the empty element (Go zero value, V-IL-116).
            let err = match il {
                Some(s) => IdentificationLink::parse(s),
                None => IdentificationLink::decode(encoded.unwrap_or("")),
            }
            .expect_err(&format!("{id}: accepted"));
            assert_eq!(codes(err.violations()), want, "{id}");
        }
    }
}

#[test]
fn dnp_encoding() {
    for v in vectors("vectors/il-dnp-encoding.json") {
        assert!(valid(&v));
        assert_eq!(
            dnp_encode(str_field(&v, "input").unwrap()),
            str_field(&v, "output").unwrap(),
            "{}",
            v["id"]
        );
    }
}

#[test]
fn oi4identifier() {
    for v in vectors("vectors/il-oi4identifier.json") {
        let id = &v["id"];
        let f = |k| str_field(&v, k).unwrap_or("");
        let built = Oi4Identifier::new(f("manufacturer_uri"), f("model"), f("product_code"))
            .serial_number(f("serial_number"))
            .build();
        if valid(&v) {
            assert_eq!(
                built.unwrap_or_else(|e| panic!("{id}: {e}")).as_str(),
                f("oi4identifier"),
                "{id}"
            );
        } else {
            let err = built.expect_err(&format!("{id}: accepted"));
            assert_eq!(codes(err.violations()), strings(&v, "violations"), "{id}");
        }
    }
}

fn check_valid_topic(v: &Value) {
    let id = &v["id"];
    let s = str_field(v, "topic").unwrap();
    let t = Topic::parse(s).unwrap_or_else(|e| panic!("{id}: {e}"));
    assert_eq!(t.to_string(), s, "{id}: round trip");
    let p = &v["parse"];
    let got = |k: &str| str_field(p, k).unwrap_or("").to_owned();
    assert_eq!(t.rule(), got("rule"), "{id}");
    assert_eq!(t.service_type().as_str(), got("service_type"), "{id}");
    assert_eq!(t.app_id().encode(), got("app_id"), "{id}");
    assert_eq!(t.app_id().as_str(), got("app_id_il"), "{id}");
    assert_eq!(t.method().as_str(), got("method"), "{id}");
    assert_eq!(t.subject().as_str(), got("resource"), "{id}");
    assert_eq!(
        t.source()
            .map(IdentificationLink::encode)
            .unwrap_or_default(),
        got("source"),
        "{id}"
    );
    assert_eq!(
        t.source()
            .map(IdentificationLink::as_str)
            .unwrap_or_default(),
        got("source_il"),
        "{id}"
    );
    assert_eq!(
        t.filter().map(ToString::to_string).unwrap_or_default(),
        got("filter"),
        "{id}"
    );
    assert_eq!(
        t.filter().map(|f| f.values()).unwrap_or_default(),
        strings(p, "filter_values"),
        "{id}"
    );
    let warnings: Vec<_> = t.warnings().iter().map(|w| w.code().to_owned()).collect();
    assert_eq!(warnings, strings(v, "warnings"), "{id}");
}

#[test]
fn topics() {
    let mut n = 0;
    for file in [
        "vectors/topic-guideline.json",
        "vectors/topic-valid.json",
        "vectors/topic-invalid.json",
    ] {
        for v in vectors(file) {
            n += 1;
            if valid(&v) {
                check_valid_topic(&v);
            } else {
                let id = &v["id"];
                let err = Topic::parse(str_field(&v, "topic").unwrap())
                    .expect_err(&format!("{id}: accepted"));
                assert_eq!(err.code(), str_field(&v, "fails").unwrap(), "{id}: {err}");
            }
        }
    }
    assert!(n >= 150, "{n} topic vectors");
}

// Every topic of a valid payload vector is a valid topic.
#[test]
fn payload_topics() {
    for file in [
        "vectors/payload-guideline.json",
        "vectors/payload-constructed.json",
    ] {
        for v in vectors(file) {
            if let (true, Some(t)) = (valid(&v), str_field(&v, "topic")) {
                let parsed = Topic::parse(t).unwrap_or_else(|e| panic!("{}: {e}", v["id"]));
                assert_eq!(parsed.to_string(), t);
            }
        }
    }
}

// The form table equals matrix/method-resource.yaml, row by row.
#[test]
fn matrix() {
    let m = load("matrix/method-resource.json");
    let rows = m["combinations"].as_array().unwrap();
    let mut allowed = 0;
    for c in rows {
        let at = format!("{}/{}", c["method"], c["resource"]);
        let method: Method = str_field(c, "method").unwrap().parse().unwrap();
        let subject: Subject = str_field(c, "resource").unwrap().parse().unwrap();
        assert_eq!(subject.kind(), str_field(c, "kind").unwrap(), "{at}");
        let form = Form::of(method, subject);
        assert_eq!(form.is_some(), c["allowed"].as_bool().unwrap(), "{at}");
        let Some(form) = form else { continue };
        allowed += 1;
        assert_eq!(
            Form::rule(method, subject),
            str_field(c, "rule").unwrap(),
            "{at}"
        );
        assert_eq!(
            form.source.as_str(),
            str_field(c, "source").unwrap(),
            "{at}"
        );
        assert_eq!(
            form.filter.as_str(),
            str_field(c, "filter").unwrap(),
            "{at}"
        );
        assert_eq!(
            form.filter_kind.map(FilterKind::as_str),
            str_field(c, "filter_rule"),
            "{at}"
        );
    }
    assert_eq!(
        rows.len(),
        Method::ALL.len() * (Resource::ALL.len() + [Service::NewDataSetWriterId].len())
    );
    assert_eq!(allowed, 29);
}
